// <auto-generated />

using System.Collections.Generic;
using CompilerBase;
using VMLAssembler;

namespace CCompiler
{
    public partial class CodeGenerator
{
        private void GenerateExpression(ASTNode node)
        {
            // 让随后生成的指令/诊断带上**这个表达式自己的**行列（语义见
            // `CodeGeneratorBase.CurrentSourceLine`/`CurrentSourceColumn`）。
            //
            // 与 `GenerateStatement` 那句是同一个道理，但**粒度细一层**：语句入口给出的是
            // 「这一句从哪开始」，而 `ReportUndefined` 要指的用户真正写错的那个名字。
            // 表达式生成是递归的 ⇒ 越往里越精确，最后停在**最内层那个节点**上
            //（`a + b + nosuch` 停在 `nosuch`，而不是 `return`）。
            //
            // 判据 `Line > 0`：`ParsePrimary` 只给原子节点盖位置，二元/一元节点的 Line 仍是 0，
            // 置 0 会把刚盖好的原子位置冲掉（那正是"列回到语句起始"的老毛病）。
            if (node.Line > 0)
            {
                CurrentSourceLine = node.Line;
                CurrentSourceOriginalLine = node.OriginalLine;
                CurrentSourceColumn = node.Column;
            }

            // asm 表达式: return asm("SYSCALL #4, ${ch}") → 执行 asm, R0 作为返回值
            if (node is AsmStatement asmExpr)
            {
                GenerateAsmStatement(asmExpr);
                // asm 结果在 R0，保留不覆盖（GenerateAsmStatement 已存到 [R12-4]）
                return;
            }

            if (node is NumberLiteral numLiteral)
            {
                var suffix = numLiteral.Suffix ?? "";
                if (numLiteral.Value is float || suffix.Contains('F') || suffix.Contains('f'))
                {
                    string flabel = $"flt_{labelCounter++}";
                    float fval = Convert.ToSingle(numLiteral.Value);
                    dataSection[flabel] = BitConverter.SingleToInt32Bits(fval);
                    AddInstruction(OpCode.MOVEF, Reg(0), Mem(flabel));
                }
                else if (suffix.Contains('L') || suffix.Contains('l'))
                {
                    // 64位整数字面量 (L/LL/UL/ULL 后缀) → MOVEL
                    // 注意: 必须在 is double 之前检查，因为溢出的 long 字面量
                    // 在 Lexer 中被转为 double (做 fallback)，但其 suffix 仍是 "L"/"LL"
                    string dlabel = $"i64_{labelCounter++}";
                    long longVal;
                    if (suffix.Contains('U') || suffix.Contains('u'))
                    {
                        // UL/ULL：**不能经 `decimal` 转 `ulong`**。
                        // `(ulong)(decimal)负数` 会抛 `Decimal.ToUInt64` 的
                        // "Value was either too large or too small for a UInt64." ——
                        // 而词法把十六进制常量装成 `unchecked((int)(uint)u64)`，
                        // 于是**凡是低 32 位最高位为 1 的常量，token 值就是负数**。
                        // 实测这一条正解释了 `bitops64.c` 编不出来：
                        //   ✗ 0xFFFFFFFFUL / 0xFFFFFFFFFFUL / 0xFFFFFFFFFFFFFFFFUL
                        //     （低 32 位都是 0xFFFFFFFF）
                        //   ✗ 0xAAAAAAAAAAAAAAAAUL(0xAAAAAAAA) / 0xCCCCCCCCCCCCCCCCUL
                        //     (0xCCCCCCCC) / 0xF0F0F0F0F0F0F0F0UL(0xF0F0F0F0)
                        //   ✓ 0x7FFFFFFFUL / 0x5555555555555555UL / 0x100000000UL
                        //     （低 32 位最高位为 0）
                        // ⇒ 一律**按位模式直接搬**，不做有符号/无符号的语义转换。
                        object hv = numLiteral.Value;
                        longVal = hv switch
                        {
                            long al => al,
                            int ai => unchecked((long)(uint)ai),
                            ulong au => unchecked((long)au),
                            uint ui => ui,
                            _ => unchecked((long)Convert.ToInt64(hv)),
                        };
                    }
                    else
                    {
                        longVal = numLiteral.Value is long l ? l : Convert.ToInt64(numLiteral.Value);
                    }
                    dataSection[dlabel] = longVal;
                    instructions.Add(new Instruction(OpCode.MOVEL, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, dlabel) }));
                }
                else if (numLiteral.Value is double)
                {
                    // 双精度字面量 (如 3.14, 10.0): 用 MOVED 加载
                    string dlabel = $"dbl_{labelCounter++}";
                    dataSection[dlabel] = (double)numLiteral.Value;
                    AddInstruction(OpCode.MOVED, Reg(0), Mem(dlabel));
                }
                else
                {
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, Convert.ToInt32(numLiteral.Value)) }));
                }
            }
            else if (node is StringLiteral strLiteral)
            {
                // 字符串常量 — 根据宽度生成对应伪指令
                string strLabel = GenerateLabel();
                if (strLiteral.Width == StringWidth.Wide)
                    dataSection[strLabel] = new VMLAssembler.DataString(strLiteral.Value, VMLAssembler.StringWidth.Wide);
                else if (strLiteral.Width == StringWidth.Unicode)
                    dataSection[strLabel] = new VMLAssembler.DataString(strLiteral.Value, VMLAssembler.StringWidth.Unicode);
                else
                    dataSection[strLabel] = strLiteral.Value;
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, strLabel) }));
            }
            else if (node is CharLiteral charLiteral)
            {
                // 字符字面量
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, (int)charLiteral.Value) }));
            }
            else if (node is SizeOfNode sizeOfNode)
            {
                int size;
                if (sizeOfNode.TypeName != null)
                    size = GetTypeSizeFromString(sizeOfNode.TypeName);
                else if (sizeOfNode.Expression != null)
                {
                    // ⚠ **数组的 `sizeof` 是总大小**（元素个数 × 元素大小），不是元素大小。
                    //   老程序那句 `memset(a, 0, sizeof(a))` 全靠它 —— 只给元素大小
                    //   就会**静默只清前几个字节**（程序照跑、结果全错），
                    //   而 `for (i = 0; i < sizeof(a); i++)` 同样中招。
                    //   最小复现与实测矩阵见 FRONTEND_DEFECTS 的「`sizeof(<数组>)` 返回元素大小」。
                    //
                    //   元素大小查 `arrayElemSize`（声明处写入）—— **不能**用
                    //   `InferExpressionType`：实测它对局部 `char[]` 给 1（对），
                    //   对全局 `char[]` 给 4（错）。只有非数组表达式才退回推断。
                    int elemSize = TryGetArrayElemSize(sizeOfNode.Expression, out int es)
                                 ? es
                                 : GetTypeSize(InferExpressionType(sizeOfNode.Expression));

                    size = TryGetArrayElementCount(sizeOfNode.Expression, out int count)
                         ? count * elemSize
                         : elemSize;
                }
                else
                    size = 4;
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, size) }));
            }

            else if (node is Identifier ident)
            {
                // 数组变量退化为指针: 生成地址而非加载内容
                //
                // ⚠ **函数内 `static` 数组必须排在最前**：它虽然登记进了 `arrayLocalVars`
                //   （见 `CodeGenerator.Functions.cs` 那段簿记），却**不在栈上** ——
                //   下面那条要求 `variables.ContainsKey(name)`（栈变量表），对它恒为假
                //   ⇒ 它会掉进再下面那条"`staticLocals` ⇒ 取值"，生成 `move @R0 [f__tbl]`
                //   （**取值**而不是取地址）。
                //   后果：`(int)tbl` 恒为 0 —— `[<数据标签>]` 这种写法在运行期解析不到
                //   （`Memory.ParseMemoryString` 只查 `Labels`，数据标签不在里面），
                //   于是"函数内静态查表"（字模、菜单、CRC 表、`sl` 的整车图形）整类失效。
                //   判据：`scripts/vml-c-probe/cases/34-static-local-array.c`。
                if (arrayLocalVars.Contains(ident.Name) && staticLocals.ContainsKey(ident.Name))
                {
                    instructions.Add(new Instruction(OpCode.MOVE,
                        new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, staticLocals[ident.Name]) }));
                }
                else if (arrayLocalVars.Contains(ident.Name) && variables.ContainsKey(ident.Name))
                {
                    // ⚠ 这条**不走 `FormatVarOffset`**（它自己拿 `variables[...]` 算偏移）——
                    //   不在这里补记一笔的话，`int a[10]; a[0]=1;` 会被误报成"未使用的局部变量"。
                    _localRefs.Add(ident.Name);
                    int arrOffset = variables[ident.Name];
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new(OperandType.REGISTER, 0), new(OperandType.REGISTER, 12) }));
                    if (arrOffset >= 0)
                        instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new(OperandType.REGISTER, 0), new(OperandType.IMMEDIATE, arrOffset) }));
                    else
                        instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new(OperandType.REGISTER, 0), new(OperandType.IMMEDIATE, -arrOffset) }));
                }
                else if ((globalArrayVars.Contains(ident.Name) && dataSection.ContainsKey(ident.Name))
                         || externArrayVariables.Contains(ident.Name))
                {
                    // 全局数组: 加载数据段标签地址 (LABEL 作为立即数地址)
                    //
                    // ⚠ 这里**只能**收数组，extern 非数组（`extern WINDOW *stdscr;`）必须
                    //   落到下面那条"全局变量"分支去**解引用**。判据是
                    //   `(int)x == (int)&x` —— 相等就说明求成了槽地址而不是槽里的值。
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, ident.Name) }));
                }
                else
                {
                    // 获取变量类型 —— 判据收在 `GetVarExprType` 一处（局部 + 全局），
                    // 别在这里再抄一遍：数组下标那条路就是因为只查局部而按 32 位读写 char 数组。
                    var varType = GetVarExprType(ident.Name);
                    var loadOp  = GetLoadInstruction(varType);

                    if (staticLocals.ContainsKey(ident.Name))
                    {
                        // static局部变量 (data section)
                        instructions.Add(new Instruction(loadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, staticLocals[ident.Name]) }));
                        EmitSignExtendIfSigned(varType);
                    }
                    else if (variables.ContainsKey(ident.Name))
                    {
                        // 局部变量
                        instructions.Add(new Instruction(loadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, $"{FormatVarOffset(ident.Name)}") }));
                        EmitSignExtendIfSigned(varType);
                    }
                    else if (enumValues.TryGetValue(ident.Name, out int enumVal))
                    {
                        // 枚举常量 → 立即数加载
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, enumVal) }));
                    }
                    else if (dataSection.ContainsKey(ident.Name) || externVariables.Contains(ident.Name))
                    {
                        // 全局变量
                        instructions.Add(new Instruction(loadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, ident.Name) }));
                        EmitSignExtendIfSigned(varType);
                    }
                    else if (ast.Functions.Exists(f => f.Name == ident.Name))
                    {
                        // 函数名在表达式中自动退化为函数指针
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, ident.Name) }));
                    }
                    else
                    {
                        // 未声明就**读** ⇒ 报错。
                        //
                        // ⚠ 这里此前是「DebugMode 下打一行中文警告、然后**静默按 0 继续**」，
                        //   同一个文件里其余四条路径（取地址 / 左值 / 数组元素 / 下标）**早就在报错**，
                        //   只有"读"这一条漏着 —— 于是 `int a = 1; return a + nosuch;` 编得过、
                        //   运行期静静算出个错答案。用户的原话正是「明明有无效标识，非要等到运行才报错」。
                        //
                        // `NoteUndefinedVariable` 发的占位值与本来的 `MOVE R0, #0` 是同一条指令
                        //   ⇒ **除了多一条诊断，生成出来的代码一字不差**（不会级联出假错）。
                        NoteUndefinedVariable(ident.Name);
                    }
                }
            }
            else if (node is BinaryOp binOp)
            {
                GenerateBinaryOp(binOp);
            }
            else if (node is UnaryOp unaryOp)
            {
                GenerateUnaryOp(unaryOp);
            }
            else if (node is CommaExpr commaExpr)
            {
                /* 逗号表达式：**先求左边（值丢弃，但副作用必须真的发生）**，再求右边 ——
                   右边的值留在 R0 作为整个表达式的值。
                   ⚠ 左边**必须真的生成代码**：`getmaxyx(win,y,x)` 这类标准头的宏
                   （展开是 `((y)=…, (x)=…)`）整套依赖左边赋值的副作用，
                   只取右边的值等于把那个赋值整个丢掉。 */
                GenerateExpression(commaExpr.Left);
                GenerateExpression(commaExpr.Right);
            }
            else if (node is Assignment assignment)
            {
                GenerateAssignment(assignment);
            }
            else if (node is FunctionCall funcCall)
            {
                GenerateFunctionCall(funcCall);
            }
            else if (node is ArrayAccess arrayAccess)
            {
                GenerateArrayAccess(arrayAccess);
            }
            else if (node is MemberAccess memberAccess)
            {
                GenerateMemberAccess(memberAccess);
            }
            else if (node is CastExpr castExpr)
            {
                // 生成表达式
                GenerateExpression(castExpr.Expression);
                // 根据目标类型进行类型转换
                var targetType  = StringToExprType(castExpr.Type);
                var currentType = InferExpressionType(castExpr.Expression);

                // 如果当前类型和目标类型不同，进行转换
                if (currentType == targetType) return;

                // 使用 SelectConversionOp 处理所有类型转换组合
                bool fromFloat = currentType == ExprType.Float, fromDouble = currentType == ExprType.Double;
                bool toFloat = targetType == ExprType.Float, toDouble = targetType == ExprType.Double;
                int fromSize = GetTypeSize(currentType), toSize = GetTypeSize(targetType);
                bool fromLong = currentType == ExprType.Long || currentType == ExprType.UnsignedLong
                                || currentType == ExprType.LongLong || currentType == ExprType.UnsignedLongLong;
                bool toLong = targetType == ExprType.Long || targetType == ExprType.UnsignedLong
                              || targetType == ExprType.LongLong || targetType == ExprType.UnsignedLongLong;

                // ⚠ **必须传"源是不是无符号"**：`(long)4000000000u` 要 `ZEXTL`（零扩展）
                //   而不是 `I2L`（符号扩展，实测得 -294967296）。这是无符号 64 位运算的前提。
                bool fromUnsigned = currentType == ExprType.UnsignedChar
                                 || currentType == ExprType.UnsignedShort
                                 || currentType == ExprType.UnsignedInt
                                 || currentType == ExprType.UnsignedLong
                                 || currentType == ExprType.UnsignedLongLong;
                var convOp = ExpressionManager.SelectConversionOp(fromSize, fromFloat, fromDouble,
                                                                   toSize, toFloat, toDouble,
                                                                   fromLong, toLong, fromUnsigned);
                if (convOp != null)
                    instructions.Add(new Instruction(convOp.Value, new List<Operand> {
                        new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0) }));
            }
            else if (node is ConditionalOp condOp)
            {
                GenerateConditionalOp(condOp);
            }
        }


        /// <summary>
        /// Maps C ExprType to ExpType for use with ExpressionManager.
        /// Int64 Hard-mode Long → I64 (uses PUSHL/POPL/CMPL/ADDL/etc. via IsLong path).
        /// </summary>
        private static ExpType CTypeToExpType(ExprType t)
        {
            if ((t == ExprType.Long || t == ExprType.UnsignedLong ||
                 t == ExprType.LongLong || t == ExprType.UnsignedLongLong)
                && VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard)
                // 无符号 long 走 U64（`IsLong()` 两者都认 ⇒ L 指令族照用；
                // 区别只在 `/` `%` `>>` 比较 与升宽的 `ZEXTL`）
                return t == ExprType.UnsignedLong || t == ExprType.UnsignedLongLong
                       ? ExpType.U64 : ExpType.I64;

            // ⚠ **无符号必须映到 `U*`**（2026-09-22 修）。
            //
            // 这里是**「无符号」进入共享层的唯一入口** —— 此前把 `UnsignedChar/Short/Int`
            // 与对应的有符号类型**写在同一个 case 里**（`Char or UnsignedChar => I8` …），
            // 符号性在这一行被丢掉，于是共享层里所有 `IsUnsigned()` 恒为假：
            // 实测 `4000000000u % 10` 走有符号 MOD 得 **-6**、`a > b` 高位为 1 时判反、
            // `(long)4000000000u` 走 `I2L` 得 **-294967296**。
            //
            // 共享层早就准备好了（`ExpType.U8..U64`、`ByteSize`、`IsLong` 都认无符号），
            // **缺的就是这一张表**。改完 `/` `%` `>>` 比较 升宽 四条路一起生效。
            return t switch
            {
                ExprType.Char           => ExpType.I8,
                ExprType.UnsignedChar   => ExpType.U8,
                ExprType.Short          => ExpType.I16,
                ExprType.UnsignedShort  => ExpType.U16,
                ExprType.Int            => ExpType.I32,
                ExprType.UnsignedInt    => ExpType.U32,
                ExprType.Long or ExprType.LongLong                    => ExpType.I32,
                ExprType.UnsignedLong or ExprType.UnsignedLongLong    => ExpType.U32,
                ExprType.Float => ExpType.F32,
                ExprType.Double => ExpType.F64,
                ExprType.CharPtr or ExprType.ShortPtr or ExprType.IntPtr or ExprType.LongPtr
                    or ExprType.FloatPtr or ExprType.DoublePtr or ExprType.VoidPtr => ExpType.Ptr32,
                _ => ExpType.I32,
            };
        }

        private ExpVar WrapExpr(ASTNode node)
        {
            var exprType = InferExpressionType(node);
            var ev = ExpVar.Eval(CTypeToExpType(exprType), () => GenerateExpression(node));
            // 指针表达式：附加所指类型大小，供 ExpressionManager 自动缩放
            if (IsPointerType(exprType))
            {
                int pointedSize = node is Identifier ident
                    ? GetPointerStepSizeForVar(ident.Name)
                    : GetPointerStepSize(exprType);
                if (pointedSize > 1)
                    ev = ev.WithPointedTypeSize(pointedSize);
            }
            return ev;
        }

        private ExpVar WrapTargetExpr(ASTNode node)
        {
            if (node is Identifier ident)
            {
                var exprType = InferExpressionType(node);
                var expType = CTypeToExpType(exprType);
                ExpVar tv;
                if (staticLocals.TryGetValue(ident.Name, out var staticLabel))
                    tv = ExpVar.Data(staticLabel, expType);
                else if (variables.TryGetValue(ident.Name, out int offset))
                    tv = ExpVar.Stack(offset, 12, expType);
                else if (dataSection.ContainsKey(ident.Name) || externVariables.Contains(ident.Name))
                    tv = ExpVar.Data(ident.Name, expType);
                else
                    return WrapExpr(node);
                if (IsPointerType(exprType))
                {
                    int pointedSize = GetPointerStepSizeForVar(ident.Name);
                    if (pointedSize > 1)
                        tv = tv.WithPointedTypeSize(pointedSize);
                }
                return tv;
            }
            return WrapExpr(node);
        }

        /// <summary>间接目标的 ++/--：使用寄存器暂存地址，手动处理 Load/Inc/Store</summary>
        private void EmitIndirectIncDec(ASTNode target, string op, bool isPostfix)
        {
            var exprType = InferExpressionType(target);
            var storeOp = GetStoreInstruction(exprType);
            int scale = 1;
            if (IsPointerType(exprType))
                scale = GetPointerStepSize(exprType);

            // 计算目标地址，保存到临时寄存器
            int addrReg = Regs!.AllocInt(instructions);
            if (target is ArrayAccess arr)
                GenerateArrayAddress(arr);
            else if (target is MemberAccess mem)
                GenerateMemberAddress(mem);
            else if (target is UnaryOp uo && uo.Op == "*")
                GenerateExpression(uo.Operand);
            instructions.Add(new Instruction(OpCode.MOVE, [Reg(addrReg), Reg(0)]));

            if (isPostfix)
            {
                // 后置: 加载旧值 → 保存到临时寄存器 → 加载+修改 → 存储 → 恢复旧值到 R0
                int savedValReg = Regs!.AllocInt(instructions);
                var loadOp = GetLoadInstruction(exprType);
                instructions.Add(new Instruction(loadOp, [Reg(0), Mem($"R{addrReg}")]));
                EmitSignExtendIfSigned(exprType);
                instructions.Add(new Instruction(OpCode.MOVE, [Reg(savedValReg), Reg(0)]));
                instructions.Add(new Instruction(loadOp, [Reg(0), Mem($"R{addrReg}")]));
                EmitSignExtendIfSigned(exprType);
                if (op == "+")
                    instructions.Add(new Instruction(OpCode.ADD, [Reg(0), Reg(0), Imm(scale)]));
                else
                    instructions.Add(new Instruction(OpCode.SUB, [Reg(0), Reg(0), Imm(scale)]));
                instructions.Add(new Instruction(storeOp, [Mem($"R{addrReg}"), Reg(0)]));
                instructions.Add(new Instruction(OpCode.MOVE, [Reg(0), Reg(savedValReg)]));
                Regs!.FreeInt(savedValReg, instructions);
            }
            else
            {
                // 前置: 加载 → 修改 → 存储
                var loadOp = GetLoadInstruction(exprType);
                instructions.Add(new Instruction(loadOp, [Reg(0), Mem($"R{addrReg}")]));
                EmitSignExtendIfSigned(exprType);
                if (op == "+")
                    instructions.Add(new Instruction(OpCode.ADD, [Reg(0), Reg(0), Imm(scale)]));
                else
                    instructions.Add(new Instruction(OpCode.SUB, [Reg(0), Reg(0), Imm(scale)]));
                instructions.Add(new Instruction(storeOp, [Mem($"R{addrReg}"), Reg(0)]));
            }
            Regs!.FreeInt(addrReg, instructions);
        }

        private void GenerateBinaryOp(BinaryOp binOp)
        {
            // 优化: x + 0 = x, x - 0 = x
            if ((binOp.Op == "+" || binOp.Op == "-") && IsZeroLiteral(binOp.Right))
            {
                GenerateExpression(binOp.Left);
                return;
            }
            // 优化: 0 + x = x
            if (binOp.Op == "+" && IsZeroLiteral(binOp.Left))
            {
                GenerateExpression(binOp.Right);
                return;
            }

            var left = WrapExpr(binOp.Left);
            var right = WrapExpr(binOp.Right);

            if (_expr!.EmitStandardBinaryOps(binOp.Op, left, right)) return;
            _expr!.EmitBitwiseOps(binOp.Op, left, right);
        }

        private static bool IsZeroLiteral(ASTNode node)
        {
            if (node is NumberLiteral num)
            {
                if (num.Value is int i && i == 0) return true;
                if (num.Value is long l && l == 0L) return true;
                if (num.Value is uint u && u == 0U) return true;
                if (num.Value is ulong ul && ul == 0UL) return true;
                if (num.Value is float f && f == 0.0f) return true;
                if (num.Value is double d && d == 0.0) return true;
            }
            return false;
        }


        private void GenerateUnaryOp(UnaryOp unaryOp)
        {
            bool isIndirect = unaryOp.Operand is ArrayAccess or MemberAccess ||
                              (unaryOp.Operand is UnaryOp u && u.Op == "*");

            if (unaryOp.IsPostfix)
            {
                // 后缀操作：EmitPostfixInc/Dec 自动处理指针缩放
                switch (unaryOp.Op)
                {
                    case "++":
                        if (isIndirect) EmitIndirectIncDec(unaryOp.Operand, "+", true);
                        else _expr!.EmitPostfixInc(WrapTargetExpr(unaryOp.Operand));
                        break;
                    case "--":
                        if (isIndirect) EmitIndirectIncDec(unaryOp.Operand, "-", true);
                        else _expr!.EmitPostfixDec(WrapTargetExpr(unaryOp.Operand));
                        break;
                }
            }
            else
            {
                bool isIndirectIncDec = isIndirect && (unaryOp.Op == "++" || unaryOp.Op == "--");
                bool isAddrOfIndirect = unaryOp.Op == "&" && isIndirect;

                // 间接 ++/-- 和 &(间接) 不需要预先计算操作数
                if (!isIndirectIncDec && !isAddrOfIndirect)
                    GenerateExpression(unaryOp.Operand);

                // 推断表达式类型
                var exprType = InferExpressionType(unaryOp);

                switch (unaryOp.Op)
                {
                    case "-":
                        _expr!.EmitNeg(WrapExpr(unaryOp.Operand));
                        break;

                    case "!":
                        _expr!.EmitNot(WrapExpr(unaryOp.Operand));
                        break;

                    case "++":
                        if (isIndirect) EmitIndirectIncDec(unaryOp.Operand, "+", false);
                        else _expr!.EmitPrefixInc(WrapTargetExpr(unaryOp.Operand));
                        break;
                    case "--":
                        if (isIndirect) EmitIndirectIncDec(unaryOp.Operand, "-", false);
                        else _expr!.EmitPrefixDec(WrapTargetExpr(unaryOp.Operand));
                        break;
                    case "&":
                        // ⚠ **必须走 GenerateAddressOf，不要在这里再写一份**。
                        //
                        // 这里原先是一份手抄的取址实现，而它把**形参**的地址算错了：
                        // 写的是 `offset = stackFrameSize - variables[name]` 再 `SUB R0, offset`。
                        // 那条公式只在「局部变量」上成立 —— 局部的偏移是**负**的（`R12-8`），
                        // 减负数得正数、正好 SUB 出 `R12-8`；而形参的偏移是**正**的（`R12+12`），
                        // 减出负数 ⇒ `if (offset > 0)` 不成立 ⇒ **一句不加，`&形参` 得到裸 `R12`**。
                        // （`stackFrameSize` 本身也只被赋过一次 0，从来没更新过。）
                        // 实测：`void par(int v){ int* p=&v; … }` 读 `*p` 得 65528（应为 42），
                        // 通过它写回也写不到 `v` 上。
                        //
                        // 而 `GenerateAddressOf` 用的 `FormatVarOffset` 是照**带符号偏移**来的
                        // （`offset >= 0 ? R12+offset : R12-offset`），本来就对 ——
                        // 两处实现只对了一半，正是本仓反复踩的「同一规则两处实现」。
                        GenerateAddressOf(unaryOp.Operand);
                        break;
                    case "*":
                        // 解引用操作: 从地址加载值
                        // R0 已经是地址，直接加载
                        // 根据指向的类型选择合适的加载指令(char*→LOADB, short*→LOADH, int*→LOAD)
                        var derefLoadOp = GetLoadInstruction(exprType);
                        instructions.Add(new Instruction(derefLoadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "R0") }));
                        EmitSignExtendIfSigned(exprType);
                        break;
                    case "~":
                        // 按位取反
                        instructions.Add(new Instruction(OpCode.NOT, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                        break;
                }
            }
        }


        private void GenerateAssignment(Assignment assignment)
        {
            // 复合赋值: target op= value → 使用 ExpressionManager 统一处理
            if (assignment.Op != null && assignment.Target is Identifier)
            {
                var target = WrapTargetExpr(assignment.Target);
                var value = WrapExpr(assignment.Value);
                _expr!.EmitCompoundAssign(target, value, assignment.Op);
                return;
            }
            // 非 Identifier 的复合赋值: 还原为 BinaryOp 走原有逻辑
            if (assignment.Op != null)
                assignment = new Assignment(assignment.Target,
                    new BinaryOp(assignment.Op, assignment.Target, assignment.Value));

            // Check if this is a struct assignment (target is a struct-type variable, not pointer)
            string targetStructType = null;
            if (assignment.Target is Identifier targetIdent &&
                variableStructTypes.TryGetValue(targetIdent.Name, out var st) &&
                variableTypes.TryGetValue(targetIdent.Name, out var vt) &&
                !IsPointerType(vt))
                targetStructType = st;
            bool isStructAssign = targetStructType != null;

            if (isStructAssign && (assignment.Value is Identifier or MemberAccess or FunctionCall or ArrayAccess))
            {
                int structSize = GetTypeSizeFromString(targetStructType);

                if (assignment.Value is FunctionCall)
                {
                    // Struct-returning function call: the return struct is placed at
                    // [SP - structSize] on the caller's stack after cleanup.
                    // Save destination address via RegisterManager.
                    int destReg = Regs!.AllocInt(instructions);
                    GenerateAddressOf(assignment.Target);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, destReg), new(OperandType.REGISTER, 0) }));
                    // Generate the function call (writes struct to [SP_orig - structSize])
                    GenerateExpression(assignment.Value);
                    // Restore destination address → R9
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 9), new(OperandType.REGISTER, destReg) }));
                    Regs.FreeInt(destReg, instructions);
                    // Source = SP - structSize → R10
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 10), new(OperandType.REGISTER, 13) }));
                    instructions.Add(new Instruction(OpCode.SUB, new List<Operand> {
                        new(OperandType.REGISTER, 10), new(OperandType.IMMEDIATE, structSize) }));
                }
                else
                {
                    // R9 = destination address
                    GenerateAddressOf(assignment.Target);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 9), new(OperandType.REGISTER, 0) }));
                    // R10 = source address
                    GenerateAddressOf(assignment.Value);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                        new(OperandType.REGISTER, 10), new(OperandType.REGISTER, 0) }));
                }

                EmitStructCopy(9, 10, structSize);
                return;
            }

            // 处理指针解引用赋值: *p = value
            if (assignment.Target is UnaryOp derefTarget && derefTarget.Op == "*")
            {
                // 获取目标类型（解引用后的类型）
                var targetType = InferExpressionType(derefTarget);
                // 先计算指针地址 → 保存到临时寄存器
                int addrReg = Regs!.AllocInt(instructions);
                GenerateExpression(derefTarget.Operand);
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                    new(OperandType.REGISTER, addrReg), new(OperandType.REGISTER, 0) }));
                // ⚠ **地址必须同时压栈**：右边那个表达式的求值**可能包含函数调用**，
                //   而被调方（也是本前端生成的）会拿 R0–R11 当临时寄存器、**不保存**它们
                //   （`RegisterManager` 的池就是 R1–R11；生成的函数体里满是
                //   `push @R0 / move @R0 … / pop @R11` 这种取临时值的写法）。
                //   ⇒ 只把地址放在寄存器里跨过调用，回来时那个寄存器**可能已经是别人的值**，
                //   于是 `*p = f()` 把结果写到一个谁也不知道的地方（实测：写丢了，
                //   调用方读到的仍是初值 0，**一个错误都不报**）。
                //
                //   实测最小复现（C，`Lib/c/graphics.h` 的 `textwidth`）：
                //   `*pw = _bgi_json_int(out, "w");` —— `textwidth("ABC")` 恒返回 **0**
                //   （同一份代码在 C++ 下返回 18/24：那边这条路径不受影响）。
                //   而 `int v = _bgi_json_int(out,"w"); *pw = v;` 是对的 ⇒ 判据收在这里。
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> {
                    new(OperandType.REGISTER, addrReg) }));
                // 再计算右侧值 → R0
                GenerateExpression(assignment.Value);
                var rhsType = InferExpressionType(assignment.Value);
                // 类型转换 — 使用 SelectConversionOp 处理所有组合
                EmitTypeConversion(rhsType, targetType);
                // 取回地址（压栈位置在实参区**之上**，被调方读 `R12+12+4i` 够不到它）
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> {
                    new(OperandType.REGISTER, addrReg) }));
                // 使用类型对应的存储指令
                var storeOp = GetStoreInstruction(targetType);
                instructions.Add(new Instruction(storeOp, new List<Operand> {
                    new(OperandType.MEMORY, $"R{addrReg}"), new(OperandType.REGISTER, 0) }));
                Regs.FreeInt(addrReg, instructions);
                return;
            }

            // 生成右侧表达式
            GenerateExpression(assignment.Value);
            // 获取右侧表达式类型
            var valueType = InferExpressionType(assignment.Value);

            // 类型检查：确保赋值兼容性
            if (assignment.Target is Identifier ident)
            {
                // 获取目标变量类型
                var targetType = variableTypes.TryGetValue(ident.Name, out var t) ? t : ExprType.Int;

                // 类型兼容性: C 语义宽松, 仅拒绝 void→non-ptr 的基本错误
                if (!IsTypeCompatible(targetType, valueType) && targetType != ExprType.Unknown && valueType != ExprType.Unknown)
                {
                    // 拒绝明显错误: void 类型值赋给非指针
                    if (valueType == ExprType.Void && !IsPointerType(targetType))
                    {
                        string varName = ident.Name;
                        string errorMsg = $"类型不兼容的赋值: 无法将类型 '{GetTypeName(valueType)}' 赋值给类型 '{GetTypeName(targetType)}' 的变量 '{varName}'";
                        throw new CodeGenerationException(ErrorCode.CodeGen_TypeMismatch, errorMsg);
                    }
                    // 其他不兼容: 降级为隐式转换 (GCC 兼容)
                }

                // 类型转换 — 使用 SelectConversionOp 处理所有组合
                EmitTypeConversion(valueType, targetType);

                var storeOp = GetStoreInstruction(targetType);
                if (staticLocals.ContainsKey(ident.Name))
                {
                    // static局部变量
                    instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, staticLocals[ident.Name]), new Operand(OperandType.REGISTER, 0) }));
                }
                else if (variables.ContainsKey(ident.Name))
                {
                    // 局部变量
                    instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, $"{FormatVarOffset(ident.Name)}"), new Operand(OperandType.REGISTER, 0) }));
                }
                else if (dataSection.ContainsKey(ident.Name) || externVariables.Contains(ident.Name))
                {
                    // 全局变量
                    instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, ident.Name), new Operand(OperandType.REGISTER, 0) }));
                }
                else
                {
                    NoteUndefinedVariable(ident.Name);
                }
            }
            else if (assignment.Target is ArrayAccess arrayAccess)
            {
                // 数组赋值：根据元素类型选择 STORE/STOREB/STOREH
                var elemType = InferExpressionType(arrayAccess);
                OpCode storeOp = GetStoreInstruction(elemType);
                int valReg = Regs!.AllocInt(instructions);
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, 0) }));
                // ⚠ **值的寄存器要先压栈保命**：`GenerateArrayAddress` 内部有**硬编码的 R1**
                //   （见它里面那句"用栈保存基地址，避免与硬编码寄存器（R1）冲突"），而
                //   `AllocInt` 是从空闲表里取的 —— R1 恰好空闲时它就会把 `valReg` 发成 R1，
                //   于是下标计算一路把值踩掉，最后存下去的是**当时的 `n`**。
                //   实测形状是教科书式的 `for (i=0; s[i]; i++) dst[n++] = s[i];` 之后再写数组：
                //   `a[n++]='B'` 存进去的是 6（那一刻的 n），而 A/C/D/z 全对
                //   （它们的 valReg 落在 R4/R9/R5，没被踩）—— 见判据 `47-array-store-regclobber.c`。
                //   压栈而不是 `ReserveInt(1)`：对"下标路径到底用哪几个寄存器"不敏感，
                //   将来那边多硬编码一个 R2 也不会再坏一次。
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, valReg) }));
                GenerateArrayAddress(arrayAccess);
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, valReg) }));
                instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, "R0"), new Operand(OperandType.REGISTER, valReg) }));
                Regs.FreeInt(valReg, instructions);
            }
            else if (assignment.Target is MemberAccess memberAccess)
            {
                string structTypeName = GetStructTypeName(memberAccess.Object);
                var bfInfo = GetBitfieldInfo(structTypeName, memberAccess.MemberName);
                int valReg = Regs!.AllocInt(instructions);
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, 0) }));
                GenerateMemberAddress(memberAccess);

                if (bfInfo.isBitfield)
                {
                    // 位域写入: 读-修改-写
                    int mask = (1 << bfInfo.bitWidth) - 1;
                    // R1 = new value (masked + shifted)
                    instructions.Add(new Instruction(OpCode.AND, new List<Operand> { new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.IMMEDIATE, mask) }));
                    if (bfInfo.bitOffset > 0)
                        instructions.Add(new Instruction(OpCode.SHL, new List<Operand> { new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.IMMEDIATE, bfInfo.bitOffset) }));
                    // R2 = storage unit (LOAD from member address)
                    int tmpReg = Regs!.AllocInt(instructions);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, tmpReg), new Operand(OperandType.MEMORY, "R0") }));
                    // Clear field in storage: R2 &= ~(mask << offset)
                    int clearMask = ~(mask << bfInfo.bitOffset);
                    instructions.Add(new Instruction(OpCode.AND, new List<Operand> { new Operand(OperandType.REGISTER, tmpReg), new Operand(OperandType.REGISTER, tmpReg), new Operand(OperandType.IMMEDIATE, clearMask) }));
                    // OR new value into storage
                    instructions.Add(new Instruction(OpCode.OR, new List<Operand> { new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, valReg), new Operand(OperandType.REGISTER, tmpReg) }));
                    Regs.FreeInt(tmpReg, instructions);
                    // STORE back
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.MEMORY, "R0"), new Operand(OperandType.REGISTER, valReg) }));
                }
                else
                {
                    string memberTypeStr = GetMemberType(structTypeName, memberAccess.MemberName);
                    ExprType memberType = StringToExprType(memberTypeStr);
                    OpCode storeOp = GetStoreOpForExprType(memberType);
                    instructions.Add(new Instruction(storeOp, new List<Operand> { new Operand(OperandType.MEMORY, "R0"), new Operand(OperandType.REGISTER, valReg) }));
                }
                Regs.FreeInt(valReg, instructions);
            }
        }


        private void GenerateArrayAccess(ArrayAccess arrayAccess)
        {
            // 生成数组地址
            GenerateArrayAddress(arrayAccess);
            // 根据元素类型选择加载指令
            var elemType = InferExpressionType(arrayAccess);
            OpCode loadOp = GetLoadInstruction(elemType);
            instructions.Add(new Instruction(loadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "R0") }));
            EmitSignExtendIfSigned(elemType);
        }


        private void GenerateArrayAddress(ArrayAccess arrayAccess)
        {
            // 判断是局部数组还是全局数组（指针变量不算数组）
            bool isLocalPtr = false;
            bool isLocalArray = false;
            if (arrayAccess.Array is Identifier arrIdent && variables.ContainsKey(arrIdent.Name))
            {
                if (variableTypes.TryGetValue(arrIdent.Name, out var vt) && IsPointerType(vt))
                    isLocalPtr = true;
                else
                    isLocalArray = true;
            }
            if (arrayAccess.Array is Identifier ident)
            {
                // VLA 变量: 从槽中加载指针，作为基地址
                if (vlaVariables.Contains(ident.Name))
                {
                    GenerateExpression(ident);
                }
                else if (isLocalPtr)
                {
                    // 指针变量：加载指针值作为基地址
                    GenerateExpression(ident);
                }
                else if (isLocalArray)
                {
                    // 局部数组：直接计算地址 R12+offset 或 R12-offset
                    // 不需要 LOAD，数组就在栈上，基地址就是 R12+offset
                    string offset = FormatVarOffset(ident.Name);
                    if (offset.StartsWith("R12+"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                        if (offsetVal != 0)
                        {
                            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                        }
                    }
                    else if (offset.StartsWith("R12-"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER,  12) }));
                        instructions.Add(new Instruction(OpCode.SUB,  new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                    }
                    else
                    {
                        // R12 (offset 0)
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                    }
                }
                else if (staticLocals.ContainsKey(ident.Name))
                {
                    // static局部数组：用data section标签地址
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, staticLocals[ident.Name]) }));
                }
                else if (dataSection.ContainsKey(ident.Name) || externVariables.Contains(ident.Name))
                {
                    // 全局**指针变量**（`char *s = "…"` / `char **p`）不是数组：下标作用在
                    // 它**指向的对象**上 ⇒ 基址是它的**值**（加载），不是它自己的槽地址（标签）。
                    // 数组反过来 —— 标签地址就是数组首地址。
                    // ⚠ 少了这条，`g_rows[1]` 会拿"存放指针的那个槽"当地址，读出槽里的字节。
                    if (!globalArrayVars.Contains(ident.Name) && IsPointerDeclName(ident.Name))
                        GenerateExpression(ident);
                    else
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, ident.Name) }));
                }
                else
                {
                    NoteUndefinedVariable(ident.Name, isArray: true);
                }
            }
            else if (arrayAccess.Array is MemberAccess memberArr)
            {
                // Struct member array: compute the address of the member
                GenerateAddress(memberArr);
            }
            else if (arrayAccess.Array is ArrayAccess nestedArray)
            {
                // 多级下标 `x[i][j]`：先取 `x[i]` 的地址，再决定**拿它当地址还是当值**。
                GenerateArrayAddress(nestedArray);

                // ⚠ 元素是**指针**时（`char **fr` 的 `fr[i]`、`char *rows[]` 的 `rows[i]`），
                //   外层下标作用在"取出来的那个指针"上 —— 基址得是它的**值**（加载）。
                //   不加载的话拿的是"存放指针的那个槽"的地址，等于把槽里的字节当字符串读：
                //   实测 `nyan_show(char ** fr)` 的 `fr[y][x]` 取到的全是空，
                //   而程序的帧数据明明是对的（三帧只发出三个 ESC）。
                if (IsPointerType(InferExpressionType(nestedArray)))
                    instructions.Add(new Instruction(GetLoadInstruction(ExprType.IntPtr),
                        new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "R0") }));
            }
            else if (arrayAccess.Array is UnaryOp unaryArr && unaryArr.Op == "*")
            {
                // (*ptr)[idx]: 基址是指针的值(它指向的地址)，不是指针变量本身的栈地址
                // GenerateExpression(ptr) 加载指针的值 = 目标数组的基址
                GenerateExpression(unaryArr.Operand);
            }
            else
            {
                // 任意表达式作为数组基址
                GenerateExpression(arrayAccess.Array);
            }

            // 处理多维数组索引
            // 对于多维数组 arr[3][4]，内存布局是行优先：arr[0][0], arr[0][1], arr[0][2], arr[0][3], arr[1][0], ...
            // 偏移量计算：index = i * 4 + j（对于 arr[i][j]）

            // 用栈保存基地址，避免与硬编码寄存器（R1）冲突
            instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));

            // 获取数组维度信息（如果可用）
            List<int?> dimensions = null;
            if (arrayAccess.Array is Identifier arrayIdent)
            {
                // 查找变量声明获取维度信息
                var varDecl = FindVariableDeclaration(arrayIdent.Name);
                if (varDecl != null && varDecl.Dimensions != null && varDecl.Dimensions.Count > 0)
                {
                    dimensions = varDecl.Dimensions;
                }
                else if (variableTypeStrings.TryGetValue(arrayIdent.Name, out var typeStr))
                {
                    // 先解析 typedef，因为 typeStr 可能是别名如 "state_t"
                    string resolvedType = ResolveTypeName(typeStr);
                    dimensions = ExtractArrayDimensions(resolvedType);
                }
            }
            else if (arrayAccess.Array is UnaryOp unaryArr2 && unaryArr2.Op == "*")
            {
                // (*ptr)[idx]: 尝试从指针类型中提取维度
                if (unaryArr2.Operand is Identifier ptrIdent && variableTypeStrings.TryGetValue(ptrIdent.Name, out var ptrTypeStr))
                {
                    // 指针类型可能是 typedef 别名如 "state_t*"
                    // 先去掉*，解析基础类型，再加回*
                    string baseWithoutStar = ptrTypeStr.Replace("*", "").Trim();
                    string resolvedBase = ResolveTypeName(baseWithoutStar);
                    dimensions = ExtractArrayDimensions(resolvedBase);
                }
            }

            // 计算总偏移量
            // 对于二维数组 arr[M][N]，偏移量 = i * N + j
            // 对于三维数组 arr[M][N][P]，偏移量 = (i * N + j) * P + k
            // 通用公式：offset = (((i0 * d1 + i1) * d2 + i2) * d3 + ...)
            
            // ── 多级下标 + 元素是指针：**不能展平** ─────────────────────────────
            //
            // `char **fr` 的 `fr[y][x]`、`char *rows[]` 的 `rows[i][j]`：**每一级下标作用在
            // 另一个对象上** —— 先 `*(base + i*4)` 取出那个指针，再对它做第二个下标。
            // 展平成一个偏移（`base + (i+j)*4`）在语义上就是错的：`rows[1]` 指向的串与
            // `rows` 的偏移毫无关系。
            //
            // ⚠ 这一段必须排在下面那个「没有维度信息就把下标相加」的兜底**之前** ——
            //   那是上一版留下的近似（注释里就写着"不正确，但至少不会崩溃"），
            //   而 nyancat / curses 的帧数组、行缓冲全是这个形状：
            //   实测 `nyan_show(char ** fr)` 三帧只发出三个 ESC，着色字符一个没读到。
            // ⚠⚠ **数组自己还有维度没走完时，不许走这一条** —— 这条是照 `T **p` 写的
            //   （"第 0 级取指针、第 1 级在它指向的对象上继续下标"），而
            //   `char *bs[2][3]` 的 `bs[i][j]` 两级下标**都作用在同一个二维数组上**：
            //   行优先展平 `base + (i*3 + j)*4` 才对，"先解引用再下标"会多读一层 ——
            //   实测 `bs[0][0]` 取出的"指针"是 `0x61003161`（= 字符串 "a1" 的头四个字节
            //   `a 1 \0 a`），随后的取值直接**内存错误**。
            //   判据：`scripts/vml-c-probe/cases/33-mdim-pointer-array.c`。
            if (arrayAccess.Indices.Count >= 2
                && arrayAccess.Array is Identifier ptrBaseIdent
                && ElementIsPointer(ptrBaseIdent.Name)
                && DeclaredArrayDims(ptrBaseIdent.Name) < arrayAccess.Indices.Count)
            {
                // 元素类型（第 0 级的步长）：指针数组/指针的指针 ⇒ 4
                var ptrElemTy = GetVarExprType(ptrBaseIdent.Name);
                // 第 1 级及以后作用在"取出来的那个指针"上；单层指针解一层就是元素本身
                int innerStride = GetTypeSize(DerefExprType(ptrElemTy));

                int mreg = Regs!.AllocInt(instructions);
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, mreg) }));   // 基地址

                // 第 0 级：base + i0 * 4 → 该槽的地址 → **解引用**取出指针
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, mreg) }));
                GenerateExpression(arrayAccess.Indices[0]);
                instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, mreg) }));
                instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, 4) }));
                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, mreg), new Operand(OperandType.REGISTER, 0) }));
                instructions.Add(new Instruction(GetLoadInstruction(ExprType.IntPtr),
                    new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, $"R{mreg}") }));
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, mreg), new Operand(OperandType.REGISTER, 0) }));

                // 第 1..n 级：在**指针指向的对象**上继续做下标
                for (int k = 1; k < arrayAccess.Indices.Count; k++)
                {
                    int stride = k == 1 ? innerStride : 4;   // 更深的层级 ExprType 表达不了 ⇒ 按指针走
                    instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, mreg) }));
                    GenerateExpression(arrayAccess.Indices[k]);
                    instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, mreg) }));
                    instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, stride) }));
                    instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, mreg), new Operand(OperandType.REGISTER, 0) }));
                }

                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, mreg) }));
                Regs.FreeInt(mreg, instructions);
                return;                                        // 地址已算完，别再走下面的公共收尾
            }

            // 如果没有维度信息，假设是一维数组
            if (dimensions == null || dimensions.Count < arrayAccess.Indices.Count)
            {
                // 生成第一个索引
                if (arrayAccess.Indices.Count > 0)
                {
                    GenerateExpression(arrayAccess.Indices[0]);
                    
                    // 对于多维数组但没有维度信息的情况，我们无法正确计算
                    // 这里我们简单地将所有索引相加（这是不正确的，但至少不会崩溃）
                    // 正确的做法应该是：第一个索引 * 第二维大小 + 第二个索引
                    // 但由于没有维度信息，我们只能简单相加
                    for (int i = 1; i < arrayAccess.Indices.Count; i++)
                    {
                        // 用 RegisterManager 保存累加结果，避免 PUSH/POP
                        int accReg = Regs!.AllocInt(instructions);
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.REGISTER, 0) }));
                        GenerateExpression(arrayAccess.Indices[i]);
                        instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.REGISTER, 0) }));
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, accReg) }));
                        Regs.FreeInt(accReg, instructions);
                    }
                }
            }
            else
            {
                // 有维度信息，正确计算偏移量
                // 用 RegisterManager 分配累加器，避免与调用约定寄存器(R1-R3)冲突
                int accReg = Regs!.AllocInt(instructions);
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.IMMEDIATE, 0) }));

                for (int i = 0; i < arrayAccess.Indices.Count; i++)
                {
                    // 生成当前索引 → R0
                    // 保存累加器值，因为 GenerateExpression 可能破坏 accReg
                    instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, accReg) }));
                    GenerateExpression(arrayAccess.Indices[i]);
                    instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, accReg) }));

                    if (i == 0)
                    {
                        // 第一个索引：acc = i0
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.REGISTER, 0) }));
                    }
                    else
                    {
                        // 后续索引：acc = acc * d_i + i_i
                        if (dimensions[i].HasValue)
                        {
                            instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.IMMEDIATE, dimensions[i].Value) }));
                        }
                        instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.REGISTER, 0) }));
                    }
                }

                // 如果索引数少于维度数（如 m[1] 对于 int m[2][3]），乘以剩余维度
                for (int j = arrayAccess.Indices.Count; j < dimensions.Count; j++)
                {
                    if (dimensions[j].HasValue)
                    {
                        instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, accReg), new Operand(OperandType.IMMEDIATE, dimensions[j].Value) }));
                    }
                }

                // 最终结果在累加器中，移动到R0
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, accReg) }));
                Regs!.FreeInt(accReg, instructions);
            }

            // 最终索引乘以元素大小
            // 获取数组元素的类型
            int elementSize = 4; // 默认int大小
            if (arrayAccess.Array is Identifier arrayIdent2)
            {
                // 优先用 GetTypeSizeFromString 从类型字符串推断（支持 typedef 数组类型）
                if (variableTypeStrings.TryGetValue(arrayIdent2.Name, out var typeStr2))
                {
                    string resolved = ResolveTypeName(typeStr2);
                    // **指针数组**（`char *rows[]`）：元素**就是那个指针**，步长 = 指针大小（4）。
                    // ⚠ 不能走下面那条"解一层引用"——`char*` 解出来是 `char`（size 1），
                    //   于是 `rows[1]` 从偏移 **1** 处读，而不是 4（实测 Q2/Q3/Q4/Q5 全空、
                    //   只有下标为 0 的 Q1 恰好对）。判据与 `InferExpressionType` 那条**同源**
                    //   （`DeclaredArrayOfPointers`），别再各写一份。
                    if (ElementIsPointer(arrayIdent2.Name))
                    {
                        elementSize = 4;
                    }
                    // 如果是指针类型，获取指向类型的元素大小
                    else if (resolved.Contains('*'))
                    {
                        string pointedType = resolved.Replace("*", "").Replace("const", "").Replace("volatile", "").Trim();
                        elementSize = GetTypeSizeFromString(pointedType);
                    }
                    else
                    {
                        /* ⚠ 与**数据段的存储宽度**共用 `ArrayElemSize` —— 这两处算的是
                           同一件事（一个元素占几字节），各写一遍就是本仓头号坑
                           「同一规则两处实现」。实测坏法：`char t[300]` 存储按 4 字节、
                           下标按 1 字节 ⇒ `t[100]` 读出 **25**（= 第 100 个字节）。
                           判据 `scripts/vml-c-probe/cases/39-array-elem-width.c`。 */
                        string baseType = StripArrayDimensions(resolved);
                        elementSize = ArrayElemSize(baseType);
                    }
                }
                // 对于 struct 数组，优先用 GetTypeSizeFromString 获取实际大小
                else if (variableStructTypes.TryGetValue(arrayIdent2.Name, out var stTypeName))
                {
                    elementSize = GetTypeSizeFromString(stTypeName);
                }
                // 从变量类型推断元素大小
                else if (variableTypes.TryGetValue(arrayIdent2.Name, out var elementType))
                {
                    if (IsPointerType(elementType))
                    {
                        elementSize = GetPointedTypeSize(elementType);
                    }
                    else
                    {
                        elementSize = GetTypeSize(elementType);
                    }
                }
            }
            else if (arrayAccess.Array is MemberAccess memberArr)
            {
                // 从成员类型推断数组元素大小
                string structType = GetStructTypeName(memberArr.Object);
                string memberTypeStr = GetMemberType(structType, memberArr.MemberName);
                // memberTypeStr is the element type without array brackets, e.g. "short" or "struct Foo"
                elementSize = GetTypeSizeFromString(memberTypeStr);
            }
            else if (arrayAccess.Array is UnaryOp unaryArr3 && unaryArr3.Op == "*")
            {
                // (*ptr)[idx]: 从指针类型推断元素大小
                if (unaryArr3.Operand is Identifier ptrIdent && variableTypeStrings.TryGetValue(ptrIdent.Name, out var ptrTypeStr2))
                {
                    // 去掉*，解析 typedef，再提取最内层元素类型
                    string baseNoStar = ptrTypeStr2.Replace("*", "").Trim();
                    string resolvedBase = ResolveTypeName(baseNoStar);
                    string innermostType = StripArrayDimensions(resolvedBase);
                    elementSize = GetTypeSizeFromString(innermostType);
                }
            }
            else if (arrayAccess.Array is ArrayAccess)
            {
                // 多级下标的**外层**：步长是**最终元素**的大小，不是上面那些"看数组声明"的分支
                // （它们一个都不匹配，落到默认的 4）。
                // `char **fr` 的 `fr[y][x]` 是 `char` ⇒ 1；默认 4 会把相邻两格错开 4 字节，
                // 表现是"格子里的字符跳着取"。
                elementSize = GetTypeSize(InferExpressionType(arrayAccess));
            }
            instructions.Add(new Instruction(OpCode.MUL, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, elementSize) }));

            // 计算最终地址（base + offset）
            // 从栈弹出基地址
            int baseReg2 = Regs!.AllocInt(instructions);
            instructions.Add(new Instruction(OpCode.POP, new List<Operand> { new Operand(OperandType.REGISTER, baseReg2) }));
            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, baseReg2) }));
            Regs.FreeInt(baseReg2, instructions);
        }

        private void GenerateMemberAccess(MemberAccess memberAccess)
        {
            string structTypeName = GetStructTypeName(memberAccess.Object);
            int memberOffset = GetMemberOffset(structTypeName, memberAccess.MemberName);

            // Determine member type for correct load instruction
            string memberTypeStr = GetMemberType(structTypeName, memberAccess.MemberName);
            // 数组成员退化为指针 (地址)
            bool isArrayMember = IsArrayMember(structTypeName, memberAccess.MemberName);
            if (isArrayMember) memberTypeStr += "*";
            ExprType memberType = StringToExprType(memberTypeStr);

            if (memberAccess.IsPointer)
            {
                GenerateExpression(memberAccess.Object);
            }
            else
            {
                GenerateAddress(memberAccess.Object);
            }

            if (memberOffset > 0)
            {
                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, memberOffset) }));
            }

            // 数组成员: 地址就是结果, 不需要LOAD
            if (!isArrayMember)
            {
                OpCode loadOp = GetLoadOpForExprType(memberType);
                instructions.Add(new Instruction(loadOp, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, "R0") }));
                EmitSignExtendIfSigned(memberType);
                // 位域: 掩码+移位提取
                var bfInfo = GetBitfieldInfo(structTypeName, memberAccess.MemberName);
                if (bfInfo.isBitfield)
                {
                    if (bfInfo.bitOffset > 0)
                        instructions.Add(new Instruction(OpCode.SHR, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, bfInfo.bitOffset) }));
                    int mask = (1 << bfInfo.bitWidth) - 1;
                    instructions.Add(new Instruction(OpCode.AND, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, mask) }));
                }
            }
        }

        private (bool isBitfield, int bitOffset, int bitWidth) GetBitfieldInfo(string structTypeName, string memberName)
        {
            var searchType = structTypeName.ToLower().Trim().TrimEnd('*', ' ');
            if (searchType.StartsWith("struct ")) searchType = searchType[7..].Trim();
            foreach (var kvp in structs)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var m in kvp.Value.Members)
                        if (m.Name == memberName && m.IsBitfield)
                            return (true, m.BitOffset, m.BitWidth);
                    return (false, 0, 0);
                }
            }
            return (false, 0, 0);
        }


        private void GenerateMemberAddress(MemberAccess memberAccess)
        {
            // 生成成员地址（不加载值），用于取地址或赋值
            // (*ptr).member 等价于 ptr->member — 检测解引用模式
            bool isPtr = memberAccess.IsPointer;
            ASTNode obj = memberAccess.Object;
            if (!isPtr && obj is UnaryOp uo && uo.Op == "*")
            {
                isPtr = true;
                obj = uo.Operand;
            }

            string structTypeName = GetStructTypeName(obj);
            int memberOffset = GetMemberOffset(structTypeName, memberAccess.MemberName);

            if (isPtr)
            {
                GenerateExpression(obj);
            }
            else
            {
                GenerateAddress(obj);
            }

            if (memberOffset > 0)
            {
                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, memberOffset) }));
            }
        }


        private void GenerateAddress(ASTNode node)
        {
            if (node is Identifier ident)
            {
                if (variables.ContainsKey(ident.Name))
                {
                    string offset = FormatVarOffset(ident.Name);
                    if (offset.StartsWith("R12+"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                        if (offsetVal != 0)
                        {
                            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                        }
                    }
                    else if (offset.StartsWith("R12-"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                        instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                    }
                    else
                    {
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                    }
                }
                else if (dataSection.ContainsKey(ident.Name) || externVariables.Contains(ident.Name))
                {
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, ident.Name) }));
                }
                else if (ast.Functions.Exists(f => f.Name == ident.Name))
                {
                    // 取函数地址: &func
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, ident.Name) }));
                }
                else
                {
                    NoteUndefinedVariable(ident.Name);
                }
            }
            else if (node is MemberAccess nestedMember)
            {
                GenerateMemberAddress(nestedMember);
            }
            else if (node is ArrayAccess arrayAccess)
            {
                GenerateArrayAddress(arrayAccess);
            }
            else if (node is FunctionCall funcCall)
            {
                // Struct-returning function call: R0 will hold the hidden return pointer
                GenerateFunctionCall(funcCall);
            }
            else if (node is UnaryOp uo && uo.Op == "&")
            {
                // &expr already yields an address, just evaluate it
                GenerateExpression(uo);
            }
            else
            {
                throw new CodeGenerationException(ErrorCode.CodeGen_CannotTakeAddress, $"无法获取表达式地址");
            }
        }


        private string GetStructTypeName(ASTNode node)
        {
            if (node is Identifier ident)
            {
                if (variableStructTypes.TryGetValue(ident.Name, out var structType))
                {
                    return structType.TrimEnd('*', ' ');
                }
            }
            else if (node is MemberAccess memberAccess)
            {
                string parentType = GetStructTypeName(memberAccess.Object);
                return GetMemberType(parentType, memberAccess.MemberName);
            }
            else if (node is ArrayAccess arrayAccess)
            {
                // Struct array element: return the struct type of the element
                return GetStructTypeName(arrayAccess.Array);
            }
            else if (node is FunctionCall funcCall)
            {
                return GetFunctionReturnType(funcCall.Name);
            }
            return "";
        }


        private string GetFunctionReturnType(string functionName)
        {
            var funcDef = ast.Functions.FirstOrDefault(f => f.Name == functionName);
            return funcDef?.ReturnType ?? "";
        }


        private int GetMemberOffset(string structTypeName, string memberName)
        {
            var searchType = structTypeName.ToLower().Trim();
            // Strip trailing pointer stars
            searchType = searchType.TrimEnd('*', ' ');
            // Remove "struct "/"union " prefix for key matching
            if (searchType.StartsWith("struct ")) searchType = searchType.Substring(7).Trim();
            else if (searchType.StartsWith("union ")) searchType = searchType.Substring(6).Trim();

            foreach (var kvp in structs)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                        if (member.Name == memberName) return member.Offset;
                    return 0;
                }
            }
            foreach (var kvp in unions)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                        if (member.Name == memberName) return member.Offset;
                    return 0;
                }
            }
            return 0;
        }


        private bool IsUnionType(string structTypeName)
        {
            string searchType = structTypeName.ToLower().Trim();
            searchType = searchType.TrimEnd('*', ' ');
            if (searchType.StartsWith("union ")) searchType = searchType.Substring(6).Trim();
            foreach (var kvp in unions)
            {
                if (kvp.Key.ToLower() == searchType)
                    return true;
            }
            return false;
        }


        private string GetMemberType(string structTypeName, string memberName)
        {
            string searchType = structTypeName.ToLower().Trim();
            searchType = searchType.TrimEnd('*', ' ');
            if (searchType.StartsWith("struct ")) searchType = searchType.Substring(7).Trim();
            else if (searchType.StartsWith("union ")) searchType = searchType.Substring(6).Trim();

            foreach (var kvp in structs)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                    {
                        if (member.Name == memberName)
                        {
                            return member.Type + new string('*', member.PointerLevel);
                        }
                    }
                }
            }
            foreach (var kvp in unions)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                    {
                        if (member.Name == memberName)
                        {
                            return member.Type + new string('*', member.PointerLevel);
                        }
                    }
                }
            }
            return "";
        }

        private bool IsArrayMember(string structTypeName, string memberName)
        {
            string searchType = structTypeName.ToLower().Trim();
            searchType = searchType.TrimEnd('*', ' ');
            if (searchType.StartsWith("struct ")) searchType = searchType.Substring(7).Trim();
            else if (searchType.StartsWith("union ")) searchType = searchType.Substring(6).Trim();

            foreach (var kvp in structs)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                        if (member.Name == memberName) return member.IsArray;
                }
            }
            foreach (var kvp in unions)
            {
                if (kvp.Key.ToLower() == searchType)
                {
                    foreach (var member in kvp.Value.Members)
                        if (member.Name == memberName) return member.IsArray;
                }
            }
            return false;
        }


        /// <summary>
        /// 本函数里**声明过**的局部量（名字 → 声明行号）。形参不进这里 —— 它们不是
        /// 「定义了却没有使用」的候选（那是调用方决定的）。由 `CountLocalVariablesEx` 填，
        /// 它在 `GenerateFunctionPrologue` 里被调用，是**局部量登记的唯一入口**。
        /// </summary>
        private readonly Dictionary<string, int> _localDecls = new();

        /// <summary>
        /// 本函数里**被用到过**的局部量名字。读 / 写 / 取地址 / 数组基址**都会经过
        /// <see cref="FormatVarOffset"/>**（要拿某个变量的内存位置就得走它），所以记录点收在那一处。
        /// </summary>
        private readonly HashSet<string> _localRefs = new();

        private string FormatVarOffset(string varName)
        {
            // 记一笔「这个局部量被用到了」—— 供「未使用局部变量」的警告用
            //（见 `_localDecls`/`_localRefs` 与 `GenerateFunction` 末尾那次比对）。
            // 放在这个函数的**入口**（不是某个分支里）：它下面有多条 return 路径。
            if (variables.ContainsKey(varName)) _localRefs.Add(varName);

            // 优先使用 variables 字典（可能已经过编译器特定的偏移调整）
            if (variables.TryGetValue(varName, out int offset))
                return offset >= 0 ? $"R12+{offset}" : $"R12{offset}";
            // 回退到 Vars
            if (Vars != null && Vars.TryGetVar(varName, out var info))
                return Vars.FormatOffset(info.Offset);
            return $"R12+0";
        }


        private void GenerateConditionalOp(ConditionalOp condOp)
        {
            _expr!.EmitConditional(
                WrapExpr(condOp.Condition),
                WrapExpr(condOp.TrueExpr),
                WrapExpr(condOp.FalseExpr));
        }


        /// <summary>
        /// 生成表达式的地址（用于取地址操作）
        /// 将地址放入R0
        /// </summary>
        /// <summary>
        /// 碰到一个**未声明的标识符**：记一条诊断、发个占位值、**继续生成**。
        ///
        /// 此前这里是 `throw new CodeGenerationException(...)` —— 5 处，而且**遇到第一个就抛**，
        /// 于是用户一次只能看到一个错（这正是用户抱怨的「现在运行就报一个错误」的编译期版本）。
        /// 改成收集之后，一个文件里写错 20 个名字会**一次全报出来**
        /// （`BuildProgram` 在 `GenerateCode` 末尾统一抛，见 `CodeGeneratorBase`）。
        ///
        /// 占位值必须发：不发的话后面的代码拿着上一条指令留在 R0 里的残值继续算，
        /// 很容易级联出一串**假**的后续错误，把真正的问题淹掉。
        /// </summary>
        private void NoteUndefinedVariable(string name, bool isArray = false)
        {
            if (ImplicitDeclarationAllowed) return;
            ReportUndefined(name,
                isArray ? ErrorCode.CodeGen_UndefinedArray : ErrorCode.CodeGen_UndefinedVariable,
                isArray ? "数组" : "变量");
            // 发 `MOVE R0, #0`：地址/值都当 0 处理，让生成继续往下走
            EmitUndefinedFallback();
        }

        private void GenerateAddressOf(ASTNode node)
        {
            if (node is Identifier addrIdent)
            {
                if (variables.ContainsKey(addrIdent.Name))
                {
                    // 局部变量/参数地址: R12 + offset (positive) or R12 - offset (negative)
                    string offset = FormatVarOffset(addrIdent.Name);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                    if (offset.StartsWith("R12+"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        if (offsetVal != 0)
                        {
                            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                        }
                    }
                    else if (offset.StartsWith("R12-"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                    }
                }
                else if (dataSection.ContainsKey(addrIdent.Name) || externVariables.Contains(addrIdent.Name))
                {
                    // 全局变量地址: 使用标签
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, addrIdent.Name) }));
                }
                else if (ast.Functions.Exists(f => f.Name == addrIdent.Name))
                {
                    // 函数指针取地址
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, addrIdent.Name) }));
                }
                else
                {
                    NoteUndefinedVariable(addrIdent.Name);
                }
            }
            else if (node is ArrayAccess arrayAddr)
            {
                GenerateArrayAddress(arrayAddr);
            }
            else if (node is MemberAccess memberAddr)
            {
                GenerateMemberAddress(memberAddr);
            }
            else if (node is UnaryOp uo && uo.Op == "&")
            {
                // &expr already yields an address, just evaluate it directly
                GenerateExpression(uo);
            }
            else if (node is UnaryOp deref && deref.Op == "*")
            {
                // &(*ptr) → ptr: dereference then address-of = just the pointer value
                GenerateExpression(deref.Operand);
            }
            else
            {
                if (node is UnaryOp uo2)
                    throw new CodeGenerationException(ErrorCode.CodeGen_UnsupportedExpression, $"不支持的表达式: UnaryOp({uo2.Op})");
                throw new CodeGenerationException(ErrorCode.CodeGen_UnsupportedExpression, VMLPlugins.Strings.UnsupportedExpression(node.GetType().Name));
            }
        }


        /// <summary>
        /// 生成左值表达式的地址（用于赋值）
        /// 将地址放入R0
        /// </summary>
        private void GenerateLValueAddress(ASTNode node)
        {
            if (node is Identifier lvalueIdent)
            {
                if (variables.ContainsKey(lvalueIdent.Name))
                {
                    string offset = FormatVarOffset(lvalueIdent.Name);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 12) }));
                    if (offset.StartsWith("R12+"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        if (offsetVal != 0)
                        {
                            instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                        }
                    }
                    else if (offset.StartsWith("R12-"))
                    {
                        int offsetVal = int.Parse(offset.Substring(4));
                        instructions.Add(new Instruction(OpCode.SUB, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.IMMEDIATE, offsetVal) }));
                    }
                }
                else if (dataSection.ContainsKey(lvalueIdent.Name) || externVariables.Contains(lvalueIdent.Name))
                {
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, lvalueIdent.Name) }));
                }
                else if (ast.Functions.Exists(f => f.Name == lvalueIdent.Name))
                {
                    // 函数指针作为左值 (如 fp = &func)
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.LABEL, lvalueIdent.Name) }));
                }
                else
                {
                    NoteUndefinedVariable(lvalueIdent.Name);
                }
            }
            else
            {
                throw new CodeGenerationException(ErrorCode.CodeGen_UnsupportedExpression, VMLPlugins.Strings.UnsupportedExpression(node.GetType().Name));
            }
        }

    }
}  // namespace
